mapper.select:
select distinct sdl.ITEM_CODE id, sdl.ITEM_VALUE text from SYS_DATADICT_LIST sdl inner join SYS_DATADICT_LIST_LINK sdll on sdl.ITEM_CODE = sdll.ITEM_CODE
and sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl.DICT_CODE = #{dict_code_child} and sdll.DICT_CODE = #{dict_code_child}
and TRIM(sdll.LINKED_ITEM_CODE) = TRIM(#{item_code_parent})
sdl.ITEM_VALUE like concat_ws('','%',#{search},'%')
ORDER BY sdl.ITEM_CODE asc

select bb.bookset_id as booksetId, bb.subject_no as subjectNo, bb.balance_date as balanceDate, bs.subject_name as subjectName, bb.bal_flag as balFlag, --IFNULL(bb.o_amt, 0) as oAmt, --IFNULL(bb.o_d_amt, 0) as oDAmt, --IFNULL(bb.o_c_amt, 0) as oCAmt, IFNULL(bb.b_amt, 0) as bAmt, IFNULL(bb.b_d_amt, 0) as bDAmt, IFNULL(bb.b_c_amt, 0) as bCAmt, bbs.acct_mode as acctMode ,bbs.acct_mode acctMode from BOK_BALANCE bb INNER JOIN BOK_BOOKSET bbs on bb.BOOKSET_ID = bbs.BOOKSET_ID inner join BOK_SUBJECT bs on bs.subject_no = bb.subject_no and bs.bookset_id = bbs.BOOKSET_ID_TMPL where 1=1
AND bb.BOOKSET_ID in
#{item}
and bb.balance_date = #{balanceDate} and bb.subject_no in
#{item}
